var a=191;var n=[{id:`cooking-191-01`,theoryId:191,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`In baker’s percentages, which ingredient is normally treated as 100%?`,ua:`Який інгредієнт зазвичай приймають за 100% у пекарських відсотках?`},explanation:{en:`Other ingredient percentages are expressed relative to the total flour weight.`,ua:`Відсотки інших інгредієнтів визначають відносно загальної маси борошна.`},options:[{id:`a`,text:{en:`Total water plus salt`,ua:`Загальну масу води й солі`}},{id:`b`,text:{en:`Total flour weight`,ua:`Загальну масу борошна`}},{id:`c`,text:{en:`Total dough weight`,ua:`Загальну масу тіста`}}],answer:{optionIds:[`b`]}},{id:`cooking-191-02`,theoryId:191,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Baker’s percentages of all dough ingredients must add up to exactly 100%.`,ua:`Сума пекарських відсотків усіх інгредієнтів має дорівнювати рівно 100%.`},explanation:{en:`Flour alone is 100%, while other ingredients add percentages on top.`,ua:`Саме борошно становить 100%, а інші інгредієнти додають свої відсотки.`},answer:{value:!1}},{id:`cooking-191-03`,theoryId:191,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match baker’s math terms to meanings.`,ua:`Поєднайте терміни пекарських розрахунків із визначеннями.`},explanation:{en:`Baker’s percentages express ingredients relative to flour, not total dough.`,ua:`Пекарські відсотки виражають складники відносно борошна, а не всього тіста.`},leftItems:[{id:`l1`,text:{en:`Flour 100%`,ua:`Борошно 100%`}},{id:`l2`,text:{en:`Water 70%`,ua:`Вода 70%`}},{id:`l3`,text:{en:`Salt 2%`,ua:`Сіль 2%`}}],rightItems:[{id:`r1`,text:{en:`Reference weight for all percentages`,ua:`Базова маса для всіх відсотків`}},{id:`r3`,text:{en:`2 g salt per 100 g flour`,ua:`2 г солі на 100 г борошна`}},{id:`r2`,text:{en:`70 g water per 100 g flour`,ua:`70 г води на 100 г борошна`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-191-04`,theoryId:191,type:`calculation`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A dough has 750 g flour and uses 2% salt. How many grams of salt?`,ua:`Тісто містить 750 г борошна та 2% солі. Скільки грамів солі потрібно?`},explanation:{en:`750 × 0.02 = 15 g.`,ua:`750 × 0,02 = 15 г.`},numericInput:{unit:`g`,unitLabel:{en:`grams`,ua:`грамів`},allowDecimals:!1},answer:{value:15,tolerance:0,unit:`g`}},{id:`cooking-191-05`,theoryId:191,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`You double a formula from 500 g to 1,000 g flour. What should happen to the ingredient weights?`,ua:`Ви збільшуєте рецептуру з 500 г до 1000 г борошна. Що зробити з масою інших складників?`},explanation:{en:`Scaling preserves the underlying baker’s percentages.`,ua:`Масштабування зберігає базові пекарські відсотки.`},options:[{id:`a`,text:{en:`Double only the salt`,ua:`Подвоїти лише сіль`}},{id:`b`,text:{en:`Scale each ingredient proportionally`,ua:`Пропорційно збільшити масу кожного інгредієнта`}},{id:`c`,text:{en:`Keep water and yeast weights unchanged regardless of dough goal`,ua:`Залишити воду й дріжджі незмінними незалежно від мети`}}],answer:{optionIds:[`b`]}},{id:`cooking-191-06`,theoryId:191,type:`calculation`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A formula contains 800 g flour and 600 g water. What is hydration in percent?`,ua:`Рецептура містить 800 г борошна й 600 г води. Яка гідратація у відсотках?`},explanation:{en:`600 ÷ 800 × 100 = 75%.`,ua:`600 ÷ 800 × 100 = 75%.`},numericInput:{unit:`%`,unitLabel:{en:`percent`,ua:`відсотків`},allowDecimals:!1},answer:{value:75,tolerance:0,unit:`%`}}];var i={theoryId:191,exercises:n};export{i as default,n as exercises,a as theoryId};